package com.deepank.careerraft.discovery;
import com.deepank.careerraft.domain.Job;import org.springframework.stereotype.Component;import java.util.*;
@Component public class AtlassianCareersJobSource implements JobSource{
 private final SimpleHttpClient http;private final HtmlJobParser parser;private final com.fasterxml.jackson.databind.ObjectMapper mapper;public AtlassianCareersJobSource(SimpleHttpClient h,HtmlJobParser p,com.fasterxml.jackson.databind.ObjectMapper m){http=h;parser=p;mapper=m;}
 public String provider(){return "atlassian_careers";}
 public List<Job>fetch(SourceDefinition d){String listingsUrl=String.valueOf(d.options().getOrDefault("listings_url","https://www.atlassian.com/endpoint/careers/listings"));int max=Integer.parseInt(String.valueOf(d.options().getOrDefault("max_detail_requests",8)));Object raw;try{raw=mapper.readValue(http.getText(listingsUrl,"application/json"),Object.class);}catch(Exception e){throw new IllegalStateException("Atlassian listings endpoint returned invalid JSON",e);}if(!(raw instanceof List<?>list))throw new IllegalStateException("Atlassian listings endpoint returned non-list JSON");List<Job>out=new ArrayList<>();Set<String>seen=new HashSet<>();for(Object item:list){if(!(item instanceof Map<?,?>rm))continue;Map<String,Object>m=cast(rm);String cat=Objects.toString(m.getOrDefault("category",""),"").trim().toLowerCase(Locale.ROOT),title=Objects.toString(m.getOrDefault("title",""),"").trim();if(!cat.equals("engineering")||!title.toLowerCase(Locale.ROOT).contains("software engineer"))continue;String id=Objects.toString(m.getOrDefault("id",""),"").trim();if(id.isBlank()||!seen.add(id))continue;String u="https://www.atlassian.com/company/careers/details/"+id;try{Map<String,String>s=parser.extract(http.getText(u,"text/html,application/xhtml+xml,*/*"));if(s==null||s.getOrDefault("description","").length()<100)continue;out.add(new Job(SourceSupport.jobId(d.name(),id),d.name(),id,s.getOrDefault("company","Atlassian"),s.getOrDefault("title",title),u,s.getOrDefault("description",""),s.get("location"),null,s.get("employment_type"),s.get("salary_text"),null,null));}catch(Exception ignored){}if(out.size()>=max)break;}return out;}
 @SuppressWarnings("unchecked")private static Map<String,Object>cast(Map<?,?>m){return(Map<String,Object>)(Map<?,?>)m;}
}
